-- ============================================================
-- CFO PESSOAL - Setup do banco no Supabase
-- Cole este script inteiro no SQL Editor do Supabase e clique em RUN.
-- ============================================================

-- 1) Tabela principal: guarda todo o estado financeiro em uma unica linha JSON.
create table if not exists finance_data (
  id text primary key,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

-- 2) Tabela de backup manual (usada pelos botoes "Fazer backup" / "Restaurar backup" do app).
create table if not exists finance_data_backup (
  id text primary key,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

-- 3) Ativa Row Level Security. O app se conecta com a service_role key
--    (que ignora RLS), entao nada quebra - isso so impede leitura/escrita
--    por qualquer chave publica/anon, mantendo os dados privados.
alter table finance_data enable row level security;
alter table finance_data_backup enable row level security;

